+// SPDX-License-Identifier: MIT
+// Copyright (c) 2025 DeepSeek
+#pragma once
+#include <cstdint>
+#include <cutlass/cutlass.h>
+namespace fused_candidates {
+using CandidateValue = uint16_t;
+constexpr uint32_t kCandidateIndexBits = 20;
+constexpr uint32_t kCandidateIndexMask = (1u << kCandidateIndexBits) - 1u;
+
+CUTLASS_DEVICE uint32_t candidate_pack_index(const uint32_t payload,
+                                             const uint32_t kv_index) {
+  return (kv_index & kCandidateIndexMask) |
+         ((payload >> 16) << kCandidateIndexBits);
+}
+
+CUTLASS_DEVICE uint32_t candidate_ordered_fp32_code(const float value) {
+  const uint32_t bits = __float_as_uint(value);
+  return (bits & 0x80000000u) ? ~bits : (bits ^ 0x80000000u);
+}
+
+CUTLASS_DEVICE uint32_t candidate_fp24_code(const float value) {
+  return candidate_ordered_fp32_code(value) >> 8;
+}
+
+CUTLASS_DEVICE uint32_t candidate_load_score_code(const CandidateValue value,
+                                                  const int32_t packed_idx) {
+  return (static_cast<uint32_t>(packed_idx) >> kCandidateIndexBits) << 16 |
+         static_cast<uint32_t>(value);
+}
+
+CUTLASS_DEVICE int32_t candidate_decode_index(const int32_t packed_idx) {
+  return static_cast<int32_t>(static_cast<uint32_t>(packed_idx) &
+                              kCandidateIndexMask);
+}
+
+CUTLASS_DEVICE void store_candidate(CandidateValue* value_dst,
+                                    int32_t* index_dst, const float bq,
+                                    const uint32_t kv_index) {
+  const uint32_t payload = candidate_fp24_code(bq);
+  __stcg(value_dst, static_cast<CandidateValue>(payload));
+  __stcg(index_dst,
+         static_cast<int32_t>(candidate_pack_index(payload, kv_index)));
+}
+
+// Stores a candidate whose fp24 code was already computed (ring records).
+CUTLASS_DEVICE void store_candidate_record(CandidateValue* value_dst,
+                                           int32_t* index_dst,
+                                           const uint32_t payload,
+                                           const uint32_t kv_index) {
+  __stcg(value_dst, static_cast<CandidateValue>(payload));
+  __stcg(index_dst,
+         static_cast<int32_t>(candidate_pack_index(payload, kv_index)));
+}
+
+}  // namespace fused_candidates

@@ -0,0 +1,208 @@
+// SPDX-License-Identifier: MIT
+// Copyright (c) 2025 DeepSeek
+// FP8 MQA-logits building blocks from DeepGEMM
+// (github.com/deepseek-ai/DeepGEMM) as of the release before its SM100 kernels
+// went MX-only: the shared-storage layout with fp32 per-key scales and fp32
+// weights, the grid-stride contiguous-KV scheduler and the 2D/3D TMA load.
+// Trimmed to what the fused kernel instantiates (no metadata schedule, no
+// multicast).
+#pragma once
+
+#include <cute/arch/copy_sm90_tma.hpp>
+#include <cutlass/arch/barrier.h>
+
+#include <deep_gemm/common/math.cuh>
+#include <deep_gemm/common/packing.cuh>
+#include <deep_gemm/common/types.cuh>
+#include <deep_gemm/common/utils.cuh>
+
+namespace fused_mqa_dg {
+namespace math = deep_gemm::math;
+
+template <uint32_t kNumHeads, uint32_t kHeadDim, bool kIsMXSF, uint32_t BLOCK_Q,
+          uint32_t SPLIT_KV, uint32_t kNumQStages, uint32_t kNumKVStages,
+          uint32_t kNumTmemStages, typename qk_dtype_t,
+          typename reduce_dtype_t = float>
+struct MQALogitsSharedStorage {
+  static constexpr bool kIsFP4 =
+      cute::is_same_v<qk_dtype_t, cutlass::float_e2m1_t>;
+
+  using Barrier = cutlass::arch::ClusterTransactionBarrier;
+  using sf_dtype_t = cute::conditional_t<kIsMXSF, uint32_t, float>;
+
+  static constexpr uint32_t kNumUTCCPAlignedElems = 128;
+  static constexpr uint32_t kQKBytesPerElem = sizeof(qk_dtype_t);
+  static constexpr uint32_t kNumQKBytesPerToken =
+      kIsFP4 ? (kHeadDim / 2) : kHeadDim;
+  static constexpr uint32_t BLOCK_QH = BLOCK_Q * kNumHeads;
+  static constexpr uint32_t UMMA_N = math::constexpr_align(BLOCK_QH, 8u);
+  // Align to one 8-row Q/K swizzle tile: FP4 uses head_dim / 2 bytes, FP8 use
+  // head_dim bytes per token
+  static constexpr uint32_t kSwizzleAlignment = 8 * kNumQKBytesPerToken;
+  static constexpr uint32_t kNumSFQ =
+      math::constexpr_align(UMMA_N, kNumUTCCPAlignedElems);
+  static constexpr uint32_t kNumSFKV =
+      math::constexpr_align(SPLIT_KV, kNumUTCCPAlignedElems);
+  static constexpr uint32_t kNumQBytesPerStage = UMMA_N * kNumQKBytesPerToken;
+  static constexpr uint32_t kNumKVBytesPerStage =
+      SPLIT_KV * kNumQKBytesPerToken;
+  static constexpr uint32_t kNumQElementsPerStage =
+      kNumQBytesPerStage / kQKBytesPerElem;
+  static constexpr uint32_t kNumKVElementsPerStage =
+      kNumKVBytesPerStage / kQKBytesPerElem;
+  // MX SF formats store per-block scale factors; FP8 stores one per-KV scale
+  // and no Q scale
+  static constexpr uint32_t kNumScaleQ = kIsMXSF ? kNumSFQ : 1;
+  static constexpr uint32_t kNumScaleKV = kIsMXSF ? kNumSFKV : SPLIT_KV;
+  // TMA destinations in shared memory must be 128-byte aligned.
+  static constexpr uint32_t kTmaAlignment = 128;
+  static constexpr uint32_t kNumWeightBytesPerRow = math::constexpr_align(
+      kNumHeads * static_cast<uint32_t>(sizeof(reduce_dtype_t)), 16u);
+  static constexpr uint32_t kNumWeightElementsPerRow =
+      kNumWeightBytesPerRow / static_cast<uint32_t>(sizeof(reduce_dtype_t));
+  static constexpr uint32_t kNumWeightBytesPerStage =
+      math::constexpr_align(BLOCK_Q * kNumWeightBytesPerRow, kTmaAlignment);
+  static constexpr uint32_t kNumWeightElementsPerStage =
+      kNumWeightBytesPerStage / static_cast<uint32_t>(sizeof(reduce_dtype_t));
+
+  DG_STATIC_ASSERT(kNumQBytesPerStage % kSwizzleAlignment == 0,
+                   "Unaligned TMA swizzling");
+  DG_STATIC_ASSERT(kNumKVBytesPerStage % kSwizzleAlignment == 0,
+                   "Unaligned TMA swizzling");
+  DG_STATIC_ASSERT(kSwizzleAlignment % 128 == 0,
+                   "TMA destination must be 128-byte aligned");
+  DG_STATIC_ASSERT(kTmaAlignment % 128 == 0,
+                   "TMA destination must be 128-byte aligned");
+  DG_STATIC_ASSERT(kNumWeightBytesPerStage % kTmaAlignment == 0,
+                   "Unaligned weight TMA stage");
+
+  alignas(kSwizzleAlignment)
+      qk_dtype_t smem_q[kNumQStages][kNumQElementsPerStage];
+  alignas(kSwizzleAlignment)
+      qk_dtype_t smem_kv[kNumKVStages][kNumKVElementsPerStage];
+  alignas(kTmaAlignment) sf_dtype_t smem_sf_q[kNumQStages][kNumScaleQ];
+  alignas(kTmaAlignment) sf_dtype_t smem_sf_kv[kNumKVStages][kNumScaleKV];
+  alignas(kTmaAlignment)
+      reduce_dtype_t smem_weights[kNumQStages][kNumWeightElementsPerStage];
+  // Barriers require 8-byte alignment, already guaranteed by the preceding
+  // TMA-aligned arrays.
+  Barrier full_q_barriers[kNumQStages];
+  Barrier empty_q_barriers[kNumQStages];
+  Barrier full_kv_barriers[kNumKVStages];
+  Barrier empty_kv_barriers[kNumKVStages];
+  Barrier full_tmem_barriers[kNumTmemStages];
+  Barrier empty_tmem_barriers[kNumTmemStages];
+  uint32_t tmem_ptr_in_smem;
+};
+
+// Grid-stride contiguous-KV scheduler: SM `s` owns Q blocks `s`, `s + kNumSMs`,
+// ..., each visiting the KV range [min k_start, max k_end) of its rows.
+template <uint32_t BLOCK_Q, uint32_t SPLIT_KV, uint32_t kNumSMs>
+struct SM100MQALogitsScheduler {
+  static constexpr bool kIsPaged = false;
+  static constexpr bool kHasPartialBlock = false;
+  static constexpr uint32_t kPageKV = 0;
+
+  uint32_t current_q_block_idx;
+  uint32_t num_q_blocks;
+  uint32_t num_q_tokens;
+  uint32_t num_kv_tokens;
+  const uint32_t* cu_seq_len_k_start;
+  const uint32_t* cu_seq_len_k_end;
+
+  CUTLASS_DEVICE SM100MQALogitsScheduler(const uint32_t& sm_idx,
+                                         const uint32_t& num_q_tokens,
+                                         const uint32_t& num_kv_tokens,
+                                         const uint32_t* cu_seq_len_k_start,
+                                         const uint32_t* cu_seq_len_k_end)
+      : current_q_block_idx(sm_idx),
+        num_q_blocks(math::ceil_div(num_q_tokens, BLOCK_Q)),
+        num_q_tokens(num_q_tokens),
+        num_kv_tokens(num_kv_tokens),
+        cu_seq_len_k_start(cu_seq_len_k_start),
+        cu_seq_len_k_end(cu_seq_len_k_end) {
+    DG_STATIC_ASSERT(kNumSMs > 0, "Invalid SM count");
+  }
+
+  // NOTE: Out-of-range rows are clamped to the last valid row
+  CUTLASS_DEVICE bool next_q_block(uint32_t& q_block_idx,
+                                   uint32_t& kv_token_base,
+                                   uint32_t& num_kv_splits) {
+    if (current_q_block_idx >= num_q_blocks) return false;
+    q_block_idx = current_q_block_idx;
+    current_q_block_idx += kNumSMs;
+    uint32_t start = cute::numeric_limits<uint32_t>::max();
+    uint32_t end = cute::numeric_limits<uint32_t>::min();
+#pragma unroll 8
+    for (uint32_t token_idx = 0; token_idx < BLOCK_Q; ++token_idx) {
+      const auto row_idx =
+          cute::min(q_block_idx * BLOCK_Q + token_idx, num_q_tokens - 1);
+      start = cute::min(start,
+                        cute::min(cu_seq_len_k_start[row_idx], num_kv_tokens));
+      end = cute::max(end, cute::min(cu_seq_len_k_end[row_idx], num_kv_tokens));
+    }
+    kv_token_base = start / 4 * 4;
+    num_kv_splits = math::ceil_div(end - kv_token_base, SPLIT_KV);
+    return true;
+  }
+
+  CUTLASS_DEVICE uint32_t
+  get_q_tma_token_base(const uint32_t& q_block_idx) const {
+    return q_block_idx * BLOCK_Q;
+  }
+
+  CUTLASS_DEVICE static uint32_t get_kv_tma_offset(
+      const uint32_t& kv_token_base, const uint32_t& kv_split_idx) {
+    return kv_token_base + kv_split_idx * SPLIT_KV;
+  }
+
+  CUTLASS_DEVICE static uint32_t get_logits_row(const uint32_t& q_block_idx,
+                                                const uint32_t& token_idx) {
+    return q_block_idx * BLOCK_Q + token_idx;
+  }
+
+  CUTLASS_DEVICE static uint32_t get_logits_col(
+      const uint32_t& kv_token_base, const uint32_t& kv_split_idx,
+      const uint32_t& math_thread_idx) {
+    return kv_token_base + kv_split_idx * SPLIT_KV + math_thread_idx;
+  }
+};
+
+// Single-CTA TMA load of a BLOCK_OUTER x BLOCK_INNER box (3D adds a batch
+// coordinate).
+template <uint32_t BLOCK_INNER, uint32_t BLOCK_OUTER, uint32_t kSwizzleMode,
+          typename dtype_t, bool kIs3DTMA = false>
+CUTLASS_DEVICE void tma_copy(
+    void const* desc_ptr, cutlass::arch::ClusterTransactionBarrier* barrier_ptr,
+    dtype_t* smem_ptr, const uint32_t& inner_idx, const uint32_t& outer_idx,
+    const uint32_t& num_tma_multicast = 1, const uint32_t& batch_idx = 0) {
+  constexpr auto kCacheHint =
+      static_cast<uint64_t>(cute::TMA::CacheHintSm90::EVICT_NORMAL);
+  constexpr uint32_t kPackFactor = deep_gemm::get_smem_pack_factor<dtype_t>();
+  DG_STATIC_ASSERT(kPackFactor == 1 or sizeof(dtype_t) == 1,
+                   "Packing expects a 1-byte storage type");
+  constexpr uint32_t BLOCK_INNER_ATOM_STORAGE =
+      kSwizzleMode == 0 ? BLOCK_INNER / kPackFactor
+                        : kSwizzleMode / sizeof(dtype_t);
+  constexpr uint32_t BLOCK_INNER_ATOM_LOGICAL =
+      BLOCK_INNER_ATOM_STORAGE * kPackFactor;
+  DG_STATIC_ASSERT(BLOCK_INNER % BLOCK_INNER_ATOM_LOGICAL == 0,
+                   "TMA inner block must contain whole atoms");
+
+#pragma unroll
+  for (uint32_t i = 0; i < BLOCK_INNER / BLOCK_INNER_ATOM_LOGICAL; ++i) {
+    if constexpr (kIs3DTMA) {
+      cute::SM90_TMA_LOAD_3D::copy(
+          desc_ptr, reinterpret_cast<uint64_t*>(barrier_ptr), kCacheHint,
+          smem_ptr + i * BLOCK_OUTER * BLOCK_INNER_ATOM_STORAGE,
+          inner_idx + i * BLOCK_INNER_ATOM_LOGICAL, outer_idx, batch_idx);
+    } else {
+      cute::SM90_TMA_LOAD_2D::copy(
+          desc_ptr, reinterpret_cast<uint64_t*>(barrier_ptr), kCacheHint,
+          smem_ptr + i * BLOCK_OUTER * BLOCK_INNER_ATOM_STORAGE,
+          inner_idx + i * BLOCK_INNER_ATOM_LOGICAL, outer_idx);
+    }
+  }
+}
+
+}  // namespace fused_mqa_dg

@@ -0,0 +1,284 @@
+// SPDX-License-Identifier: MIT
+// Copyright (c) 2025 DeepSeek
+// Dense FP8 MQA scoring of one 8-row block over its whole KV range: DeepGEMM's
+// SM100 MQA logits pipeline (contiguous KV, 32 heads, D = 128) with the logits
+// store replaced by a per-score policy. Used by the <= 4K resident kernel and
+// by the persistent kernel's exact recovery rescan.
+//
+// Roles (384 threads): warps 0-7 reduce the 32 heads (4 rows per warpgroup),
+// warp 8 loads Q and the weights, warp 9 the KV tiles and their scales, warp 10
+// issues the UMMAs, warp 11 is idle.
+//
+// Policy interface (all called by the math warps):
+//   kWeightScale, kScoreScale     score = (sum_h kWeightScale * w_h * (s_h +
+//   |s_h|)) * kScoreScale * scale_kv begin_block(sched, q_block, query_base)
+//   after the block's Q / weights landed begin_split(split, query_base) before
+//   the split's scores score(i, kv_offset, kv_lane, split, score)    row
+//   query_base + i of the warpgroup end_split(split, num_splits, kv_base) after
+//   the split's scores end_block(sched, q_block)                     before the
+//   block's Q stage is released
+#pragma once
+
+#include <cutlass/arch/reg_reconfig.h>
+#include <cute/arch/cluster_sm90.hpp>
+#include <cute/arch/copy_sm90_desc.hpp>
+
+#include <deep_gemm/common/cute_tie.cuh>
+#include <deep_gemm/common/ring_pipeline.cuh>
+#include <deep_gemm/common/utils.cuh>
+#include <deep_gemm/mma/sm100.cuh>
+#include <deep_gemm/ptx/ld_st.cuh>
+#include <deep_gemm/ptx/tcgen05.cuh>
+#include <deep_gemm/ptx/utils.cuh>
+
+#include "deep_gemm_compat.cuh"
+
+namespace fused_mqa_dense {
+using namespace deep_gemm;
+
+constexpr uint32_t kNumHeads = 32, kHeadDim = 128, BLOCK_Q = 8, SPLIT_KV = 256;
+constexpr uint32_t kNumKVStages = 2, kNumTmemStages = 2;
+constexpr uint32_t UMMA_M = 128, UMMA_N = BLOCK_Q * kNumHeads, UMMA_K = 32;
+using Scheduler =
+    fused_mqa_dg::SM100MQALogitsScheduler<BLOCK_Q, SPLIT_KV, 4096>;
+using SharedStorage = fused_mqa_dg::MQALogitsSharedStorage<
+    kNumHeads, kHeadDim, false, BLOCK_Q, SPLIT_KV, 1, kNumKVStages,
+    kNumTmemStages, cutlass::float_e4m3_t, float>;
+
+// The policy's state lives in dynamic shared memory right after the pipeline
+// storage. Barrier words are zeroed before init: the persistent kernel reuses
+// this memory between rescans.
+template <typename Policy>
+CUTLASS_DEVICE void score_block(const Scheduler& block, Policy& policy,
+                                const cute::TmaDescriptor& tensor_map_q,
+                                const cute::TmaDescriptor& tensor_map_kv,
+                                const cute::TmaDescriptor& tensor_map_sf_kv,
+                                const cute::TmaDescriptor& tensor_map_weights) {
+  const auto warp_idx = cutlass::canonical_warp_idx_sync();
+  const auto lane_idx = ptx::get_lane_idx();
+  constexpr uint32_t kSpecWarpStart = 8;
+  constexpr uint32_t SMEM_Q_SIZE_PER_STAGE = BLOCK_Q * kNumHeads * kHeadDim;
+  constexpr uint32_t SMEM_KV_SIZE_PER_STAGE = SPLIT_KV * kHeadDim;
+  constexpr uint32_t SMEM_SF_KV_SIZE_PER_STAGE = SPLIT_KV * sizeof(float);
+  constexpr uint32_t SMEM_WEIGHT_SIZE_PER_STAGE =
+      BLOCK_Q * kNumHeads * sizeof(float);
+  constexpr uint32_t kNumTmemCols =
+      utils::get_num_aligned_tmem_cols<UMMA_N * kNumTmemStages>();
+
+  if (warp_idx == kSpecWarpStart) {
+    cute::prefetch_tma_descriptor(&tensor_map_q);
+    cute::prefetch_tma_descriptor(&tensor_map_weights);
+    cute::prefetch_tma_descriptor(&tensor_map_kv);
+    cute::prefetch_tma_descriptor(&tensor_map_sf_kv);
+  }
+
+  extern __shared__ __align__(SharedStorage::kSwizzleAlignment)
+      uint8_t smem_buffer[];
+  auto& smem = *reinterpret_cast<SharedStorage*>(smem_buffer);
+  if (warp_idx == kSpecWarpStart + 1 and cute::elect_one_sync()) {
+    const auto init = [](auto& barrier, uint32_t count) {
+      *reinterpret_cast<volatile uint64_t*>(&barrier) = 0;
+      barrier.init(count);
+    };
+    init(smem.full_q_barriers[0], 1);
+    init(smem.empty_q_barriers[0], 256 + 32);
+#pragma unroll
+    for (uint32_t i = 0; i < kNumKVStages; ++i) {
+      init(smem.full_kv_barriers[i], 1);
+      init(smem.empty_kv_barriers[i], 256);
+    }
+#pragma unroll
+    for (uint32_t i = 0; i < kNumTmemStages; ++i) {
+      init(smem.full_tmem_barriers[i], 1);
+      init(smem.empty_tmem_barriers[i], 256);
+    }
+    cutlass::arch::fence_barrier_init();
+  }
+  __syncwarp();
+  if (warp_idx == kSpecWarpStart + 2)
+    cute::TMEM::Allocator1Sm().allocate(kNumTmemCols, &smem.tmem_ptr_in_smem);
+  __syncthreads();
+
+  RingPipeline<1> q_pipeline;
+  RingPipeline<kNumKVStages> kv_pipeline;
+  RingPipeline<kNumTmemStages> tmem_pipeline;
+  cudaGridDependencySynchronize();
+
+  uint32_t q_block_idx, kv_base, num_kv_splits;
+  if (warp_idx == kSpecWarpStart) {
+    cutlass::arch::warpgroup_reg_dealloc<56>();
+    if (cute::elect_one_sync()) {
+      Scheduler scheduler = block;
+      while (scheduler.next_q_block(q_block_idx, kv_base, num_kv_splits)) {
+        CUTE_TIE_DECL(q_pipeline.advance(), q_stage_idx, q_phase);
+        smem.empty_q_barriers[q_stage_idx].wait(q_phase ^ 1);
+        const uint32_t q_token_base =
+            scheduler.get_q_tma_token_base(q_block_idx);
+        fused_mqa_dg::tma_copy<kHeadDim, BLOCK_Q * kNumHeads, 0>(
+            &tensor_map_q, &smem.full_q_barriers[q_stage_idx],
+            smem.smem_q[q_stage_idx], 0, q_token_base * kNumHeads);
+        fused_mqa_dg::tma_copy<kNumHeads, BLOCK_Q, 0>(
+            &tensor_map_weights, &smem.full_q_barriers[q_stage_idx],
+            smem.smem_weights[q_stage_idx], 0, q_token_base);
+        smem.full_q_barriers[q_stage_idx].arrive_and_expect_tx(
+            SMEM_Q_SIZE_PER_STAGE + SMEM_WEIGHT_SIZE_PER_STAGE);
+      }
+    }
+    __syncwarp();
+  } else if (warp_idx == kSpecWarpStart + 1) {
+    cutlass::arch::warpgroup_reg_dealloc<56>();
+    Scheduler scheduler = block;
+    while (scheduler.next_q_block(q_block_idx, kv_base, num_kv_splits)) {
+#pragma unroll 1
+      for (uint32_t kv_split_idx = 0; kv_split_idx < num_kv_splits;
+           ++kv_split_idx) {
+        if (cute::elect_one_sync()) {
+          CUTE_TIE_DECL(kv_pipeline.advance(), kv_stage_idx, kv_phase);
+          smem.empty_kv_barriers[kv_stage_idx].wait(kv_phase ^ 1);
+          const uint32_t kv_tma_offset =
+              scheduler.get_kv_tma_offset(kv_base, kv_split_idx);
+          fused_mqa_dg::tma_copy<kHeadDim, SPLIT_KV, 0>(
+              &tensor_map_kv, &smem.full_kv_barriers[kv_stage_idx],
+              smem.smem_kv[kv_stage_idx], 0, kv_tma_offset);
+          fused_mqa_dg::tma_copy<SPLIT_KV, 1, 0>(
+              &tensor_map_sf_kv, &smem.full_kv_barriers[kv_stage_idx],
+              smem.smem_sf_kv[kv_stage_idx], kv_tma_offset, 0);
+          smem.full_kv_barriers[kv_stage_idx].arrive_and_expect_tx(
+              SMEM_KV_SIZE_PER_STAGE + SMEM_SF_KV_SIZE_PER_STAGE);
+        }
+        __syncwarp();
+      }
+    }
+  } else if (warp_idx == kSpecWarpStart + 2) {
+    cutlass::arch::warpgroup_reg_dealloc<56>();
+    DG_TRAP_ONLY_DEVICE_ASSERT(ptx::ld_shared(&smem.tmem_ptr_in_smem) == 0);
+    auto instr_desc = cute::UMMA::make_instr_desc<
+        cutlass::float_e4m3_t, cutlass::float_e4m3_t, float, UMMA_M, UMMA_N,
+        cute::UMMA::Major::K, cute::UMMA::Major::K>();
+    auto runtime_instr_desc = cute::UMMA::make_runtime_instr_desc(instr_desc);
+    Scheduler scheduler = block;
+    while (scheduler.next_q_block(q_block_idx, kv_base, num_kv_splits)) {
+      CUTE_TIE_DECL(q_pipeline.advance(), q_stage_idx, q_phase);
+      smem.full_q_barriers[q_stage_idx].wait(q_phase);
+      for (uint32_t kv_split_idx = 0; kv_split_idx < num_kv_splits;
+           ++kv_split_idx) {
+        CUTE_TIE_DECL(kv_pipeline.advance(), kv_stage_idx, kv_phase);
+        smem.full_kv_barriers[kv_stage_idx].wait(kv_phase);
+        if (cute::elect_one_sync()) {
+          // One UMMA per math warpgroup: KV rows [128 i, 128 i + 128) x all 256
+          // Q rows.
+#pragma unroll
+          for (uint32_t i = 0; i < 2; ++i) {
+            CUTE_TIE_DECL(tmem_pipeline.advance(), tmem_stage_idx, tmem_phase);
+            const uint32_t tmem_addr = tmem_stage_idx * UMMA_N;
+            smem.empty_tmem_barriers[tmem_stage_idx].wait(tmem_phase ^ 1);
+            ptx::tcgen05_after_thread_sync();
+#pragma unroll
