+struct CodesPolicy {
+  static constexpr float kWeightScale = 1.0f, kScoreScale = 0.5f;
+  uint8_t* codes;
+  uint32_t query_base;
+  CUTLASS_DEVICE void begin_block(const Scheduler&, uint32_t, uint32_t base) {
