+      v.x = v.x < 0 ? -1 : v.x - s;
+      v.y = v.y < 0 ? -1 : v.y - s;
+      v.z = v.z < 0 ? -1 : v.z - s;
+      v.w = v.w < 0 ? -1 : v.w - s;
